package findu.backend.review.entity; import findu.backend.global.entity.BaseEntity;import findu.backend.user.entity.User;import jakarta.persistence.*;import lombok.*;@Entity @Getter @Builder @NoArgsConstructor(access=AccessLevel.PROTECTED)@AllArgsConstructor @Table(name="reviews")public class Review extends BaseEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="reviewer_id")User reviewer;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="reviewee_id")User reviewee;@Column(nullable=false)int rating;@Column(columnDefinition="TEXT")String comment;}
